"analyticsTitle":"T4","ordinal":4,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Vulnerability"}},{"id":"f8b37e96-8d51-5057-adf8-dd05d32b0c9f","stableKey":"T5","sectionKey":"classify-statements","sectionTitle":"Classify statements","questionType":"matching","analyticsTitle":"T5","ordinal":5,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Threat"}},{"id":"64fefc49-c496-570b-8e4b-04454228d25b","stableKey":"T6","sectionKey":"classify-statements","sectionTitle":"Classify statements","questionType":"matching","analyticsTitle":"T6","ordinal":6,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Risk"}},{"id":"45f448f1-2527-5caf-aa1f-68e4cdf38852","stableKey":"T7","sectionKey":"classify-statements","sectionTitle":"Classify statements","questionType":"matching","analyticsTitle":"T7","ordinal":7,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Vulnerability"}},{"id":"51b9aa86-f1ad-5b7a-b753-a726fd891ebc","stableKey":"T8","sectionKey":"classify-statements","sectionTitle":"Classify statements","questionType":"matching","analyticsTitle":"T8","ordinal":8,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Vulnerability"}}],"activityId":"51e954bd-5f59-54ad-985f-1827d5ec7d81","title":"Vulnerability, threat and risk","gitPath":"week-5/threat-vulnerability-risk/index.html"},{"kind":"new_activity","activityKey":"week5-controls-matching","version":"1.0.0","versionId":"59e345d4-e741-5ee2-8ee9-e3d1720b2076","contentHash":"6886e549b9aa676c87c9bb8caa062beedec4c9176d52051aac8e2cb7ca50a4b6","maxScore":8,"questionCount":8,"weekNumber":5,"sessionNumber":2,"allowEmptyUnpublished":false,"assignmentId":"640b66fa-f76c-571d-bd5f-0568d39aa5a1","questions":[{"id":"471a0e65-b982-59bf-ad8f-04fbcdf4be71","stableKey":"C1","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C1","ordinal":1,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Patching and updates"}},{"id":"18282f43-f13c-5deb-ab1e-7ef7425ffd53","stableKey":"C2","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C2","ordinal":2,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Access control"}},{"id":"32dc7632-973f-5908-a1b0-44f77e060cd5","stableKey":"C3","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C3","ordinal":3,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Input validation"}},{"id":"7cc8c9d9-5959-5eff-9aaf-ae03dc0c8950","stableKey":"C4","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C4","ordinal":4,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Secrets hygiene"}},{"id":"f34f2a9e-0d9f-5745-954b-ec5b6fb67eba","stableKey":"C5","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C5","ordinal":5,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Secrets hygiene"}},{"id":"866c72e2-104f-5b5e-898e-2377ade29c9a","stableKey":"C6","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C6","ordinal":6,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Access control"}},{"id":"a3d18839-5e57-559e-a940-4e09b408107a","stableKey":"C7","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C7","ordinal":7,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Detection"}},{"id":"d3f92a14-409d-50e1-b8a2-ce0adc1a5721","stableKey":"C8","sectionKey":"match-controls","sectionTitle":"Match controls","questionType":"matching","analyticsTitle":"C8","ordinal":8,"maxScore":1,"marking":{"mode":"classification","correctCategoryId":"Detection"}}],"activityId":"a6948d4c-8920-5761-80c3-ff498c49edfe","title":"Choosing defensive controls","gitPath":"week-5/controls-matching/index.html"},{"kind":"new_activity","activityKey":"week5-secure-rewrite","version":"1.0.0","versionId":"78bc8195-9e9e-56b9-a8bb-883fea790fbf","contentHash":"1775cad54dad17a9abe619b8fbcaa17c9401669921b37f82fc2f9dc0caba4ae4","maxScore":6,"questionCount":6,"weekNumber":5,"sessionNumber":2,"allowEmptyUnpublished":false,"assignmentId":"159b63be-bcfa-5726-a1a3-a9992d8b18f9","questions":[{"id":"5cb1c21b-a409-5671-951c-b0f32d0c2db2","stableKey":"R1","sectionKey":"secure-rewrites","sectionTitle":"Secure rewrites","questionType":"single","analyticsTitle":"R1","ordinal":1,"maxScore":1,"marking":{"mode":"single-choice","correctOptionId":"b"}},{"id":"72536c81-05fd-5c5f-9bd3-debf79e6c93a","stableKey":"R2","sectionKey":"secure-rewrites","sectionTitle":"Secure rewrites","questionType":"single","analyticsTitle":"R2","ordinal":2,"maxScore":1,"marking":{"mode":"single-choice","correctOptionId":"a"}},{"id":"4a96b252-f11f-5927-a047-24fdef634ad8","stableKey":"R3","sectionKey":"secure-rewrites","sectionTitle":"Secure rewrites","questionType":"single","analyticsTitle":"R3","ordinal":3,"maxScore":1,"marking":{"mode":"single-choice","correctOptionId":"b"}},{"id":"ae50fb2a-2faf-59d2-9f1b-b9cb1f7e40a4","stableKey":"R4","sectionKey":"secure-rewrites","sectionTitle":"Secure rewrites","questionType":"single","analyticsTitle":"R4","ordinal":4,"maxScore":1,"marking":{"mode":"single-choice","correctOptionId":"a"}},{"id":"607797d9-f8d0-5bce-88bf-6c8ecab70607","stableKey":"R5","sectionKey":"secure-rewrites","sectionTitle":"Secure rewrites","questionType":"single","analyticsTitle":"R5","ordinal":5,"maxScore":1,"marking":{"mode":"single-choice","correctOptionId":"a"}},{"id":"408b90fe-822e-5445-b5e6-a0b758d12aaf","stableKey":"R6","sectionKey":"secure-rewrites","sectionTitle":"Secure rewrites","questionType":"single","analyticsTitle":"R6","ordinal":6,"maxScore":1,"marking":{"mode":"single-choice","correctOptionId":"a"}}],"activityId":"759f6400-6956-5edc-896f-4259aea21997","title":"Improving insecure implementations","gitPath":"week-5/secure-rewrite/index.html"}]$a1catalogue$;
  item jsonb;
  question jsonb;
  v_activity learning.activities%rowtype;
  v_version learning.activity_versions%rowtype;
  v_activity_id uuid;
  v_question_rows integer;
  v_attempts integer;
  v_delivery integer;
  v_assignments integer;
  v_languages integer;
  v_expected_count integer;
  v_week_id uuid;
begin
  for item in
    select value from jsonb_array_elements(catalogue)
  loop
    v_expected_count := (item->>'questionCount')::integer;

    if item->>'kind' = 'new_activity' then
      select * into v_activity
      from learning.activities
      where stable_key = item->>'activityKey';
      if found then
        if v_activity.id is distinct from (item->>'activityId')::uuid
           or v_activity.title is distinct from item->>'title'
           or v_activity.git_path is distinct from item->>'gitPath'
           or v_activity.active is not true then
          raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: activity % exists with incompatible identity', item->>'activityKey';
        end if;
      end if;
    end if;

    select version.* into v_version
    from learning.activity_versions as version
    join learning.activities as activity on activity.id = version.activity_id
    where activity.stable_key = item->>'activityKey'
      and version.version = item->>'version';

    if not found then
      continue;
    end if;

    if v_version.id is distinct from (item->>'versionId')::uuid
       or v_version.content_hash is distinct from item->>'contentHash'
       or v_version.question_count is distinct from v_expected_count
       or v_version.max_score is distinct from (item->>'maxScore')::numeric
       or v_version.retired_at is not null then
      raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: % % metadata is incompatible', item->>'activityKey', item->>'version';
    end if;

    select count(*)::integer into v_question_rows
    from learning.questions
    where activity_version_id = v_version.id;

    select count(*)::integer into v_attempts
    from learning.attempts
    where activity_version_id = v_version.id;

    select count(*)::integer into v_delivery
    from learning.activity_delivery
    where activity_version_id = v_version.id;

    select count(*)::integer into v_assignments
    from learning.activity_assignments
    where activity_version_id = v_version.id;

    select count(*)::integer into v_languages
    from learning.activity_version_languages
    where activity_version_id = v_version.id;

    if v_version.published_at is not null then
      perform learning.assert_unit3_batch_a1_questions_match(item, v_version.id);
    elsif v_question_rows = 0 then
      if coalesce((item->>'allowEmptyUnpublished')::boolean, false) is not true then
        raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: unexpected empty unpublished version for % %', item->>'activityKey', item->>'version';
      end if;
      if v_attempts <> 0 or v_delivery <> 0 or v_assignments <> 0 or v_languages <> 0 then
        raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: residue % % has unexpected dependents', item->>'activityKey', item->>'version';
      end if;
    else
      if v_attempts <> 0 then
        raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: unpublished % % has learner attempts', item->>'activityKey', item->>'version';
      end if;
      perform learning.assert_unit3_batch_a1_questions_match(item, v_version.id);
    end if;
  end loop;

  for item in
    select value from jsonb_array_elements(catalogue)
  loop
    if item->>'kind' = 'new_activity' then
      insert into learning.activities (id, module_id, stable_key, title, activity_type, git_path, active)
      values (
        (item->>'activityId')::uuid,
        (select id from learning.modules where course_id = (select id from learning.courses where stable_key = 'ocr-level-3-it') and stable_key = 'unit-3-cyber-security'),
        item->>'activityKey',
        item->>'title',
        'practice',
        item->>'gitPath',
        true
      )
      on conflict (stable_key) do nothing;
      v_activity_id := (item->>'activityId')::uuid;
    else
      select id into strict v_activity_id
      from learning.activities
      where stable_key = item->>'activityKey';
    end if;

    insert into learning.activity_versions (
      id, activity_id, version, content_hash, max_score, question_count, published_at
    )
    values (
      (item->>'versionId')::uuid,
      v_activity_id,
      item->>'version',
      item->>'contentHash',
      (item->>'maxScore')::numeric,
      (item->>'questionCount')::integer,
      null
    )
    on conflict (activity_id, version) do nothing;

    select * into strict v_version
    from learning.activity_versions
    where id = (item->>'versionId')::uuid;

    if v_version.published_at is null then
      for question in
        select value from jsonb_array_elements(item->'questions')
      loop
        insert into learning.questions (
          id, activity_version_id, stable_key, section_key, section_title, question_type, analytics_title, ordinal, max_score
        )
        values (
          (question->>'id')::uuid,
          v_version.id,
          question->>'stableKey',
          question->>'sectionKey',
          question->>'sectionTitle',
          question->>'questionType',
          question->>'analyticsTitle',
          (question->>'ordinal')::integer,
          (question->>'maxScore')::numeric
        )
        on conflict (activity_version_id, stable_key) do nothing;

        if question->'marking' is not null and question->'marking' <> 'null'::jsonb then
          insert into learning.question_marking (question_id, spec)
          values ((question->>'id')::uuid, question->'marking')
          on conflict (question_id) do nothing;
        end if;
      end loop;

      update learning.activity_versions
      set published_at = '2026-08-30T21:00:00Z'::timestamptz
      where id = v_version.id
        and published_at is null;
    end if;

    v_week_id := case (item->>'weekNumber')::integer
      when 1 then (select id from learning.curriculum_weeks where module_id = (select id from learning.modules where course_id = (select id from learning.courses where stable_key = 'ocr-level-3-it') and stable_key = 'unit-3-cyber-security') and stable_key = 'week-1')
      when 2 then (select id from learning.curriculum_weeks where module_id = (select id from learning.modules where course_id = (select id from learning.courses where stable_key = 'ocr-level-3-it') and stable_key = 'unit-3-cyber-security') and stable_key = 'week-2')
      when 5 then (select id from learning.curriculum_weeks where module_id = (select id from learning.modules where course_id = (select id from learning.courses where stable_key = 'ocr-level-3-it') and stable_key = 'unit-3-cyber-security') and stable_key = 'week-5')
      else null
    end;

    insert into learning.activity_delivery (
      activity_version_id, academic_year_id, curriculum_week_id, week_number, session_number, sort_order, active
    )
    select
      v_version.id,
      academic_year.id,
      v_week_id,
      (item->>'weekNumber')::integer,
      (item->>'sessionNumber')::integer,
      0,
      true
    from learning.academic_years as academic_year
    where academic_year.active
      and not exists (
        select 1
        from learning.activity_delivery as delivery
        where delivery.activity_version_id = v_version.id
          and delivery.academic_year_id = academic_year.id
          and delivery.group_id is null
      )
    order by academic_year.code
    limit 1;

    insert into learning.activity_assignments (id, group_id, activity_version_id, required, active)
    select
      (item->>'assignmentId')::uuid,
      learner_group.id,
      v_version.id,
      true,
      true
    from learning.groups as learner_group
    where learner_group.code = 'CYBER-TEST-A'
    on conflict (group_id, activity_version_id) do nothing;
  end loop;
end;
$recovery$;

create or replace function learning.assert_unit3_batch_a1_questions_match(item jsonb, version_id uuid)
returns void
language plpgsql
set search_path = ''
as $assert$
declare
  v_question_rows integer;
  v_matched_count integer;
  v_marking_count integer;
  v_expected_count integer;
begin
  v_expected_count := jsonb_array_length(item->'questions');

  select count(*)::integer into v_question_rows
  from learning.questions
  where activity_version_id = version_id;

  if v_question_rows <> v_expected_count then
    raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: % % question row count is incompatible', item->>'activityKey', item->>'version';
  end if;

  select count(*)::integer into v_matched_count
  from jsonb_array_elements(item->'questions') as expected
  join learning.questions as question
    on question.id = (expected.value->>'id')::uuid
   and question.activity_version_id = version_id
   and question.stable_key = expected.value->>'stableKey'
   and question.section_key = expected.value->>'sectionKey'
   and question.section_title = expected.value->>'sectionTitle'
   and question.question_type = expected.value->>'questionType'
   and question.analytics_title = expected.value->>'analyticsTitle'
   and question.ordinal = (expected.value->>'ordinal')::integer
   and question.max_score = (expected.value->>'maxScore')::numeric;

  if v_matched_count <> v_expected_count then
    raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: % % questions do not match the canonical catalogue', item->>'activityKey', item->>'version';
  end if;

  select count(*)::integer into v_marking_count
  from jsonb_array_elements(item->'questions') as expected
  left join learning.question_marking as marking
    on marking.question_id = (expected.value->>'id')::uuid
  where (
      jsonb_typeof(expected.value->'marking') = 'null'
      and marking.question_id is not null
    ) or (
      jsonb_typeof(expected.value->'marking') = 'object'
      and marking.spec is distinct from expected.value->'marking'
    );

  if v_marking_count <> 0 then
    raise exception 'UNIT3_BATCH_A1_RECOVERY_CONFLICT: % % marking specs are incompatible', item->>'activityKey', item->>'version';
  end if;
end;
$assert$;

revoke all on function learning.apply_unit3_batch_a1_recovery() from public;
revoke all on function learning.assert_unit3_batch_a1_questions_match(jsonb, uuid) from public;

select learning.apply_unit3_batch_a1_recovery();

commit;
